// Liquid chrome: the room's brightness becomes a fake surface that reflects a Y2K chrome
// sky (white to ice blue, a hard dark horizon, a champagne-gold ground). Hi-hats catch
// four-point star glints on the brightest spots. param[0] shine, param[1] glints.
float aspect = resolution.x / resolution.y;
vec3 Y = vec3(0.299, 0.587, 0.114);
vec3 cam = source(uv);
float l = dot(cam, Y);

// The surface: a normal from the brightness gradient, a fixed fraction of the frame height.
// Wide taps, so skin, hair and grass read as smooth metal, not speckle.
vec2 e = vec2(1.0 / aspect, 1.0) * 0.01;
float le = dot(source(uv + vec2(e.x, 0.0)), Y);
float lw = dot(source(uv - vec2(e.x, 0.0)), Y);
float ln = dot(source(uv + vec2(0.0, e.y)), Y);
float ls = dot(source(uv - vec2(0.0, e.y)), Y);
vec3 n = normalize(vec3((lw - le) * 3.5, (ls - ln) * 3.5, 1.0));
float soft = (l * 2.0 + le + lw + ln + ls) / 6.0;

// Where the reflection looks: up the normal, plus the brightness, plus a slow liquid wobble
// that the bass shakes harder.
float wobble = sin(uv.y * 11.0 + time * 1.3) * (0.05 + 0.15 * audio.low)
             + sin(uv.x * 7.0 - time * 0.9) * 0.04;
float r = n.y * 0.9 + (soft - 0.5) * mix(1.2, 3.2, param[0]) + wobble;

// Folded into repeating bands: more shine, more horizons in each shape.
float h = abs(fract(r * mix(0.6, 1.6, param[0]) + 0.5) * 2.0 - 1.0);

// The chrome sky and ground, meeting at a hard dark horizon.
vec3 sky = mix(palette[1], palette[2], smoothstep(0.52, 0.75, h));
sky = mix(sky, palette[4], smoothstep(0.78, 1.0, h));
vec3 ground = mix(palette[0], palette[3], smoothstep(0.46, 0.08, h));
vec3 env = mix(ground, sky, smoothstep(0.49, 0.515, h));

// Dark stays dark, so the people keep their shape.
vec3 metal = env * (0.3 + 0.85 * smoothstep(0.03, 0.55, l));

// Glints: a grid of cells, each with one spot; a bright spot lights up a star whose arms grow
// on the hi-hat. The 3x3 neighbours let an arm cross into the next cell.
float cs = 1.0 / 12.0;
vec2 g = vec2(uv.x * aspect, uv.y) / cs;
vec2 cell = floor(g);
float glint = 0.0;
float reach = clamp(0.45 + 0.9 * audio.high + 0.3 * audio.beat, 0.0, 1.4);
for (int j = -1; j <= 1; j++) {
  for (int i = -1; i <= 1; i++) {
    vec2 id = cell + vec2(float(i), float(j));
    vec2 c = id + 0.2 + 0.6 * vec2(hash(id), hash(id + vec2(7.1, 3.3)));
    // Each spot lives in cycles of about two thirds of a second, fading in and out, so a
    // star never pops; the hi-hat makes more of them live.
    float phase = time * 1.5 + hash(id + vec2(2.0, 8.0));
    float life = sin(fract(phase) * 3.14159);
    float lit = step(hash(id + floor(phase)), param[1] * (0.12 + 0.45 * audio.high));
    if (lit > 0.5) {
      float b = smoothstep(0.5, 0.85, dot(source(vec2(c.x * cs / aspect, c.y * cs)), Y));
      vec2 d = g - c;
      float arms = exp(-abs(d.y) * 45.0) * max(0.0, 1.0 - abs(d.x) / reach)
                 + exp(-abs(d.x) * 45.0) * max(0.0, 1.0 - abs(d.y) / reach);
      float core = exp(-dot(d, d) * 90.0);
      glint += b * life * (arms * 0.8 + core);
    }
  }
}
vec3 spark = mix(palette[4], palette[3], 0.25) * min(glint, 1.5);

return mix(cam, metal + spark, strength);

// The two-step chop: the picture cut into horizontal bands. On the kick some bands slip
// sideways and wrap round, some hold the last frame (a stutter), like a chopped vocal.
// Odd bands land late when swing is up: the shuffle. param[0] slices, param[1] swing.
float count = floor(mix(3.0, 18.0, param[0]));
float band = floor(uv.y * count);
float odd = mod(band, 2.0);

// The pattern re-deals twice a second, so each kick cuts a different set of bands.
float deal = floor(time * 2.0);
float pick = hash(vec2(band, deal));

// Even bands hit on the onset; odd bands hit on a bump that peaks halfway down the beat's
// fall, later than the kick, by as much as swing asks.
float onset = audio.beat * audio.beat;
float late = 4.0 * audio.beat * (1.0 - audio.beat);
float hit = mix(onset, mix(onset, late, param[1]), odd) * strength;

float dir = hash(vec2(band, deal + 13.0)) < 0.5 ? -1.0 : 1.0;
float slip = pick > 0.45 ? dir * (0.03 + 0.12 * hash(vec2(band, deal + 5.0))) * hit : 0.0;
vec3 c = source(vec2(fract(uv.x + slip), uv.y));

// The stutter: a few bands hold the last frame while the hit is high.
float hold = pick < 0.2 ? smoothstep(0.15, 0.6, hit) * 0.92 : 0.0;
c = mix(c, lastFrame(uv), hold);

// A thin gold cut line along the top of a band that moved.
float edge = 1.0 - smoothstep(0.0, 0.05, fract(uv.y * count));
c += palette[3] * edge * clamp(abs(slip) * 10.0 + hold, 0.0, 1.0) * 0.6;
return c;
